import WIDTHS from '../image-widths.json'

// Serves a WebP with a JPG fallback. `src` is the original JPG path
// (e.g. "/harvard-team.jpg"); the .webp siblings are generated by
// scripts/convert-images.mjs: the full-width one plus -480/-800/-1280 copies
// below the photo's own width (recorded in src/image-widths.json). With
// `sizes` (the photo's rendered width), the browser picks the smallest copy
// that stays sharp on the screen in hand. The <img> keeps the styling class,
// and the global `picture { display: contents }` rule keeps layout identical
// to a bare <img>.
const STEPS = [480, 800, 1280]

export default function Picture({ src, alt, className, sizes, loading = 'lazy', decoding = 'async', fetchPriority, ...rest }) {
  const webp = src.replace(/\.jpe?g$/i, '.webp')
  const full = WIDTHS[src.replace(/^\//, '')]
  const srcSet = full
    ? [...STEPS.filter(w => w < full).map(w => `${webp.replace(/\.webp$/, `-${w}.webp`)} ${w}w`), `${webp} ${full}w`].join(', ')
    : webp
  return (
    <picture>
      <source srcSet={srcSet} sizes={full ? sizes : undefined} type="image/webp" />
      <img
        src={src}
        alt={alt}
        className={className}
        loading={loading}
        decoding={decoding}
        fetchpriority={fetchPriority}
        {...rest}
      />
    </picture>
  )
}
